export function createPhoneMessages(ctx,texture){
 function rect(x,y,w,h,r,color){ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(x+r,y);ctx.arcTo(x+w,y,x+w,y+h,r);ctx.arcTo(x+w,y+h,x,y+h,r);ctx.arcTo(x,y+h,x,y,r);ctx.arcTo(x,y,x+w,y,r);ctx.fill();}
 function base(color){ctx.fillStyle=color;ctx.fillRect(0,0,256,448);ctx.fillStyle='#fff';ctx.font='16px Arial';ctx.textAlign='left';ctx.fillText('07:15',16,27);ctx.fillRect(211,17,25,9);rect(103,15,50,14,7,'#09090e');}
 function home(){base('#3c294d');const g=ctx.createLinearGradient(0,70,230,430);g.addColorStop(0,'#6e8dc4');g.addColorStop(1,'#b47296');ctx.fillStyle=g;ctx.fillRect(0,45,256,403);rect(17,57,222,77,18,'#ffffff22');ctx.fillStyle='#fff';ctx.textAlign='right';ctx.font='24px Arial';ctx.fillText('יום הניסוי',224,88);ctx.font='16px Arial';ctx.fillText('יום חדש מתחיל',224,116);
 const apps=[['WhatsApp','#20b66b'],['מצלמה','#758492'],['תמונות','#dca959'],['יומן','#dfe5ef'],['מזג אוויר','#497eb9'],['הגדרות','#697584'],['מפות','#4f9b81'],['שעון','#243344']];apps.forEach(([name,color],i)=>{const x=18+(i%4)*59,y=157+Math.floor(i/4)*91;rect(x,y,44,44,11,color);ctx.fillStyle=i===3?'#38404b':'#fff';ctx.textAlign='center';ctx.font=i===0?'bold 29px Arial':'bold 24px Arial';ctx.fillText(i===0?'☎':i===3?'8':i===1?'●':i===2?'✿':i===6?'↗':'◉',x+22,y+31);ctx.fillStyle='#fff';ctx.font='12px Arial';ctx.fillText(name,x+22,y+61);if(i===0){rect(x+32,y-6,17,17,9,'#dd4149');ctx.font='12px Arial';ctx.fillText('1',x+41,y+7);}});rect(18,364,220,58,19,'#ffffff35');ctx.font='17px Arial';ctx.textAlign='center';ctx.fillStyle='#fff';ctx.fillText('טלפון     הודעות     Safari',128,400);texture.needsUpdate=true;}
 function chat(){base('#eee9df');ctx.fillStyle='#146757';ctx.fillRect(0,42,256,65);ctx.fillStyle='#fff';ctx.textAlign='right';ctx.font='bold 25px Arial';ctx.fillText('אמא',225,72);ctx.font='14px Arial';ctx.fillText('WhatsApp • מחוברת',225,94);rect(17,139,222,150,13,'#fff');ctx.fillStyle='#273c38';ctx.font='21px Arial';ctx.textAlign='right';['בהצלחה בניסוי 8!','אני בדיוק רואה','את החדשות.'].forEach((line,i)=>ctx.fillText(line,224,177+i*34));ctx.font='12px Arial';ctx.fillStyle='#81908a';ctx.fillText('07:15',224,277);rect(12,378,232,44,19,'#fff');ctx.fillStyle='#89958e';ctx.font='15px Arial';ctx.fillText('הודעה',224,407);texture.needsUpdate=true;}
 return{home,chat};
}
